      'Get-MessageTrace -SenderAddress "{{USERNAME}}@{{DOMAIN}}" -StartDate (Get-Date).AddDays(-3) -EndDate (Get-Date) | Select-Object Received, SenderAddress, RecipientAddress, Subject, Status',
      'Search-UnifiedAuditLog -StartDate (Get-Date).AddDays(-3) -EndDate (Get-Date) -UserIds "{{USERNAME}}" -Operations "New-InboxRule", "Set-InboxRule" -ResultSize 50 | Format-List CreationDate, Operations, UserIds, AuditData',
      'Resolve-DnsName -Type TXT -Name "_dmarc.{{DOMAIN}}"',
      'New-TransportRule -Name "SOC{{TICKET_ID}} bloqueo BEC" -SenderDomainIs "dominio-lookalike.com" -SetSCL 9',
