    escalation: 'Si la transferencia ya se ejecutó, es P1: IR lead, CISO, legal y contacto inmediato con el banco para reversión; involucre a la Fiscalía si el fraude fue consumado. Si el spam comprometió varios buzones, declare incidente mayor y siga RB-SOC-031.',
    english_customer_response_template: 'Hi {{USERNAME}}, we detected fraudulent emails impersonating our executives requesting an urgent wire transfer. We blocked the sender, removed the messages, and confirmed with Finance that no payment was sent. Your mailbox was also sending spam, so we reset your password and signed out all sessions. Please verify any payment request by phone with the requester before acting, using a known number, never one from the email.',
    english_technical_explanation: 'Business Email Compromise (T1566) attempt at {{TIMESTAMP}}: executive impersonation via lookalike domain plus a compromised internal mailbox relaying spam. Detection: EmailEvents inbound senders spoofing {{DOMAIN}} and Get-MessageTrace volume anomaly; Search-UnifiedAuditLog ruled out attacker inbox rules. Containment: transport rule blocking the lookalike domain (SCL 9), session revocation and password reset on the compromised mailbox, campaign purged. DMARC reviewed at p=none; hardening requested. Finance confirmed no funds were transferred.',
    keywords: ['bec', 'business email compromise', 'fraude', 'wire fraud', 'transferencia', 'spoofing', 'spf', 'dkim', 'dmarc', 'spam interno', 'internal spam', 'relay', 'lookalike', 'dominio suplantado', 'message trace', 'unified audit log'],
