        action: 'Verificación: confirmar cese de intentos anómalos tras la contención',
        command: 'SigninLogs | where UserPrincipalName == "{{USERNAME}}" | where TimeGenerated > ago(1h) | project TimeGenerated, IPAddress, Location, ResultType | order by TimeGenerated desc',
        expected: 'Solo inicios del usuario desde su ubicación y dispositivo habituales; intentos del atacante rechazados.',
        explanation: 'Si persisten intentos exitosos, trate la cuenta como comprometida y siga RB-SOC-002 y RB-SOC-006.',
