    escalation: 'Si hay un inicio exitoso confirmado del atacante o la fatiga terminó en aprobación, es P1: aplique RB-SOC-002 y RB-SOC-006 y notifique al IR lead. Si el patrón se repite en varias cuentas, escale al equipo de Identity para políticas de acceso condicional y number matching.',
    english_customer_response_template: 'Hi {{USERNAME}}, we detected unusual sign-in attempts on your account, including repeated multi-factor approval requests you did not initiate. We blocked the suspicious session, reset your password, and signed out all devices. Please sign in again with the temporary password and deny any approval request you did not start. If your phone keeps buzzing with MFA prompts, report it immediately: that is an attacker trying to wear you down.',
    english_technical_explanation: 'Entra ID sign-in anomalies for {{USERNAME}} at {{TIMESTAMP}}: risky sign-in plus impossible travel between locations, and a burst of failed MFA prompts from {{SOURCE_IP}} consistent with MFA fatigue (T1078 valid credentials). Detection: SigninLogs timeline and Get-MgRiskDetection; user confirmed no travel. Containment: Revoke-MgUserSession plus forced password reset; MFA number matching recommended. Verification: no successful anomalous sign-ins in the following 24 hours; failed attempts from the attacking IP continued without success.',
    keywords: ['sign-in riesgoso', 'risky sign-in', 'viaje imposible', 'impossible travel', 'mfa fatigue', 'fatiga mfa', 'push bombing', 'identity protection', 'get-mgriskdetection', 'signinlogs', 'entra', 'azure ad', 'geolocalizacion', 'number matching', 'revocar sesion', 'usuario riesgoso', 'risky user'],
