    english_customer_response_template: 'Hi {{USERNAME}}, we found that an attacker stole an active session token from your computer and was using your account without your password. We revoked every session and token, so the attacker is now signed out, and we required you to re-register your authentication app. Please sign in again with your new password. Your computer was cleaned and scanned; report any suspicious popup or login you did not perform.',
    english_technical_explanation: 'Token/PRT theft confirmed for {{USERNAME}} at {{TIMESTAMP}}: successful non-interactive sign-ins from {{SOURCE_IP}} in AADNonInteractiveUserSignInLogs with no matching interactive attempts (T1003 credential theft via infostealer, browser session cookies). Containment: Revoke-MgUserSession invalidating the stolen tokens, MFA re-registration and device re-enrollment; host cleaned with Get-MpThreat and full scan. Verification: no successful non-interactive sign-ins from the malicious IP after revocation; Graph and mailbox access reviewed for data exposure.',
    keywords: ['prt', 'primary refresh token', 'robo de token', 'token theft', 'cookie', 'sesion', 'session hijacking', 'no interactivo', 'non-interactive', 'aadnoninteractiveusersigninlogs', 'revoke session', 'aitm', 'infostealer', 're-registro mfa', 'sesion persistente'],
