    english_customer_response_template: 'Hi {{USERNAME}}, your account was repeatedly targeted by password guessing attempts from an external address. The attempts failed, and we blocked the attacking address at the firewall. As a precaution we unlocked your account and verified no successful sign-in happened from the attacker. Please make sure your password is unique and long; if you use it anywhere else, change it there too.',
