      'Get-ADUser -Filter { ServicePrincipalName -ne "$null" } -Properties ServicePrincipalName, PasswordLastSet | Select-Object Name, PasswordLastSet, ServicePrincipalName | Sort-Object PasswordLastSet',
      'SecurityEvent | where EventID == 4771 | where TimeGenerated > ago(24h) | summarize Fallos = count() by TargetUserName, IpAddress | order by Fallos desc',
      'Get-FileHash .\Rubeus.exe -Algorithm SHA256',
      'Disable-ADAccount -Identity "{{USERNAME}}"',
