    english_customer_response_template: 'Hi {{USERNAME}}, your account was locked repeatedly because a device or application was trying to log in with an old saved password. We identified the source and updated it, and your account is unlocked now. Please sign in normally. If your account locks again within the hour, let us know immediately so we can check your mobile phone and any saved passwords.',
