    escalation: 'Es P1 por defecto: el borrado de logs durante o cerca de actividad maliciosa es destrucción de evidencia; notifique al IR lead inmediatamente y aplique RB-SOC-028 para preservar memoria y artefactos del host. Si ocurrió en {{DOMAIN_CONTROLLER}}, declare incidente mayor (RB-SOC-031).',
    english_customer_response_template: 'Hi {{USERNAME}}, we detected that the security log on one of your systems was cleared, which attackers often do to hide their tracks. We preserved the remaining logs, blocked the account that performed the deletion, and restored monitoring. If you or a colleague cleared logs for disk space, please tell us now: it changes the investigation path. No action is needed from you otherwise.',
    english_technical_explanation: 'Security log clearing (anti-forensics) on {{HOSTNAME}} at {{TIMESTAMP}}: Event 1102 in SecurityEvent executed by SubjectUserName with no associated change ticket; System log event 104 also present. Investigation: pre-clearing activity reconstructed from SIEM buffer and local .evtx exported with wevtutil for evidence. Containment: executing account disabled, host isolated. Remediation: security log size increased (wevtutil sl) and forwarding verified. Treated as P1 with IR lead engagement; chain of custody documented for the exported logs.',
    keywords: ['1102', '104', 'borrado de logs', 'log clearing', 'anti-forense', 'anti-forensics', 'destruccion de evidencia', 'wevtutil', 'evtx', 'clear event log', 'registro de seguridad', 'security log', 'rotacion de logs', 'subjectusername', 'visibilidad'],
