    english_customer_response_template: 'Hi {{USERNAME}}, our endpoint protection detected malware on your computer. It was blocked before it could run, and we cleaned the machine and ran a full scan that came back clean. No data was accessed and your account was not compromised. Please be careful with downloads and email attachments, and let us know if you noticed anything unusual before the alert.',
    english_technical_explanation: 'EDR/Defender alert on {{HOSTNAME}} at {{TIMESTAMP}}: SecurityAlert triage followed by Get-MpComputerStatus (protections healthy), Get-MpThreat and Get-MpThreatDetection (threat, severity, DidThreatExecute, process and resources). Classification: blocked execution (DidThreatExecute false); no anomalous interpreter lineage in DeviceProcessEvents. Remediation: Update-MpSignature, Remove-MpThreat, full scan clean; file hash blocked tenant-wide. Verification: no active threats and no new alerts for 24 hours; closed as contained with IOC documentation.',
