    english_customer_response_template: 'Hi {{USERNAME}}, we found malware that had installed itself as a fake Windows service and a registry start-up entry on your computer, so it could relaunch at every boot with full privileges. We removed both, quarantined the malicious file, and a full scan is clean. Your account was not compromised. Please tell us about any software you installed before the alert.',
    english_technical_explanation: 'Autostart persistence (T1547) on {{HOSTNAME}} at {{TIMESTAMP}}: new service via event 7045 with binary in Temp running as SYSTEM, plus a run key entry in CurrentVersion\\Run pointing to the same payload. Detection: SecurityEvent 7045 pivot and Get-ItemProperty on HKLM/HKCU run keys. Containment: service stopped and disabled (sc config), run key removed with Remove-ItemProperty, host isolated. Remediation: sc delete, payload quarantined, hash blocked, full scan clean; other persistence mechanisms checked. Verification: no new 7045 events and clean run keys after 24 hours.',
