    english_customer_response_template: 'Hi {{USERNAME}}, we found an information-stealing program on your computer that exports saved passwords and browser sessions. We isolated the machine, removed the malware, and reset your password and multi-factor registration, because stolen sessions can bypass passwords. Please check your accounts for anything unfamiliar and never save corporate passwords in the browser on that machine again.',
