    verification: 'Todos los IOCs del reporte fueron barridos contra el histórico (hash, IP, dominio) con cero hits o con casos abiertos y gestionados; la hipótesis de caza quedó validada o descartada con datos; los hallazgos útiles entraron al backlog de detecciones como reglas nuevas (RB-SOC-027).',
    evidence_to_collect: [
      'Documento de la caza: hipótesis, queries KQL/SPL, ventanas y resultados',
      'Lista de IOCs barridos con su fuente y fecha',
      'Export de los hits confirmados y su derivación a casos',
      'Registro de falsos positivos y afinamientos propuestos',
    ],
    escalation: 'Hallazgos con compromiso confirmado escalan como P1/P2 al IR lead con el runbook de la técnica; recurrencia de la misma técnica sin cobertura genera un hallazgo de detección formal para el equipo de ingeniería (RB-SOC-027) y se reporta en las métricas del SOC (RB-SOC-030).',
    english_customer_response_template: 'Hello, as part of our proactive threat hunting program we swept our environment for the indicators published in the latest campaign report. We found no traces of compromise in our tenant, and we used the exercise to add one new detection rule to our monitoring. No action is required from any user; we will keep hunting on a scheduled basis and communicating findings.',
    english_technical_explanation: 'Hypothesis-driven hunt plus IOC sweep on {{TENANT}} at {{TIMESTAMP}}: hypothesis mapped T1059.001 encoded PowerShell to DeviceProcessEvents fields; IOCs (hash, IP) swept over 30 days in KQL and SPL (index=main sourcetype=WinEventLog:Security by src). Results: no hits for the campaign indicators; two hosts flagged for legitimate encoded admin scripts (documented as false positives). Detection gap for scheduled task creation from user-writable paths converted into a Sigma rule request. Coverage documented for the next hunting cycle.',
    keywords: ['threat hunting', 'caza de amenazas', 'hipotesis', 'hypothesis', 'ioc sweep', 'barrido ioc', 'kql', 'spl', 'splunk', 'retro-hunt', 'proactivo', 'cobertura', 'coverage', 'detection gap', 'backlog detecciones', 'cert'],
