    english_customer_response_template: 'Hello team, the detection gap identified in the last hunting cycle has been closed: a new Sigma rule now detects suspicious scheduled task creation from user-writable paths. The rule is versioned in our repository, converted to Splunk syntax, and validated against 30 days of history with an acceptable false-positive rate. It will generate alerts from now on, mapped to MITRE T1053.005.',
    english_technical_explanation: 'Sigma rule creation from a hunting finding on {{TENANT}} at {{TIMESTAMP}}: logic first validated in KQL against real DeviceProcessEvents events; rule written in YAML (logsource process_creation windows, selection on Image/CommandLine with Temp path, condition selection) with T1053.005 tags; validated with sigma check and converted with sigma convert to Splunk SPL. Retro-hunt over 30 days tuned the rule to a low FP rate; deployed to the SIEM and committed to the rules repository with peer review. Coverage gap closed and documented for metrics.',
    keywords: ['sigma', 'regla sigma', 'sigma rule', 'yaml', 'pysigma', 'sigma check', 'sigma convert', 'deteccion', 'detection engineering', 'spl', 'kql', 'portabilidad', 'repositorio', 'mitre', 'tags', 'false positive rate', 'retro-hunt'],
