    english_customer_response_template: 'Hi {{USERNAME}}, to preserve the evidence of the security incident we kept your computer running but isolated, and captured its memory, network state, and logs before any cleaning. Your machine is now being remediated and returned to you shortly. Please do not attempt to reinstall or clean anything yourself, and tell us anything unusual you noticed before the alert.',
