        order: 1,
        action: 'Preparación: verificar que el host de laboratorio reporta sano al EDR y al SIEM',
        command: 'Get-MpComputerStatus | Format-List AMServiceEnabled, RealTimeProtectionEnabled',
        expected: 'Ambos campos True: el agente está activo y los eventos del simulacro llegarán al SIEM para poder medir.',
        explanation: 'Un simulacro con el agente caído no mide nada: confirme la ingestión, tome el snapshot restaurable de la VM y registre el T0 previsto.',
