      'New-Item -ItemType Directory -Path C:\\Drill -Force; 1..200 | ForEach-Object { Set-Content -Path ("C:\\Drill\\doc{0}.txt" -f $_) -Value drill }; Get-ChildItem C:\\Drill -Filter *.txt | Rename-Item -NewName { $_.Name -replace "txt", "locked" }',
      'vssadmin delete shadows /all /quiet',
      'SecurityAlert | where TimeGenerated > ago(1h) | where CompromisedEntity == "{{HOSTNAME}}" | project TimeGenerated, DisplayName, AlertSeverity | order by TimeGenerated asc',
      'New-NetFirewallRule -DisplayName "SOC Drill {{TICKET_ID}}" -Direction Outbound -Action Block',
      'Disable-NetFirewallRule -DisplayName "SOC Drill {{TICKET_ID}}"',
