        command: 'DeviceProcessEvents | where TimeGenerated > ago(24h) | where ProcessCommandLine has_any ("vssadmin delete shadows", "Rubeus", "kerberoast") | summarize Hosts = dcount(DeviceName), Ejecuciones = count()',
        expected: 'Número de hosts distintos con comandos de ataque: el conteo exacto define el nivel de crisis y el paquete de contención.',
        explanation: 'La equivalencia SPL: index=main sourcetype=WinEventLog:Security EventCode=4688 | stats count by host, user | sort - count; documente el total en la bitácora.',
