        expected: 'Archivo(s) web nuevos en el árbol de IIS con su hash y con w3wp.exe como proceso creador: la subida entró por HTTP.',
        explanation: 'Si el creador es w3wp.exe, el dropper entró por la propia aplicación (endpoint de subida explotado); si es otro proceso, continúe el linaje de ese proceso (RB-SOC-013).',
