      'DeviceFileEvents | where TimeGenerated > ago(7d) | where ActionType == "FileCreated" | where FolderPath contains "inetpub" | where FileName has_any (".asp", ".aspx", ".ashx") | project TimeGenerated, DeviceName, FileName, FolderPath, SHA256, InitiatingProcessFileName | order by TimeGenerated desc',
      'Get-FileHash "C:\\inetpub\\wwwroot\\uploads\\cmd.aspx" -Algorithm SHA256',
