      'Get-MpThreat | Format-List ThreatName, SeverityID, DidThreatExecute, Resources',
      'DeviceProcessEvents | where TimeGenerated > ago(4h) | where InitiatingProcessFileName =~ "w3wp.exe" | summarize Ejecuciones = count()',
