    escalation: 'Toda web shell es P1: acceso no autorizado confirmado a un servidor público; escale al IR lead de inmediato (RB-SOC-031) y evalúe el aislamiento del servidor (RB-SOC-029). Si el log muestra descargas de datos o creación de cuentas, siga RB-SOC-012 y RB-SOC-028.',
    english_customer_response_template: 'Hello, our security monitoring detected unauthorized code running on one of our public web servers and we removed it within the hour. The attackers used a flaw in an application feature to plant a backdoor; we blocked their addresses, closed the flaw with the application team, and rotated the server credentials. No user action is required. We will keep the system owner updated through this ticket until the verification completes.',
    english_technical_explanation: 'Web shell (T1505.003) confirmed on IIS server {{HOSTNAME}} at {{TIMESTAMP}}: w3wp.exe process lineage executing cmd.exe and powershell.exe detected in DeviceProcessEvents; shell file located via DeviceFileEvents as a newly created .aspx under the wwwroot uploads folder, created by w3wp.exe itself, indicating HTTP upload through the exploited public-facing application (T1190). Evidence preserved with SHA256 hash and chain of custody. IIS logs (sourcetype=iis) identified the uploading and accessing source IPs (203.0.113.10 and 203.0.113.11). Containment: attacker IPs blocked at host firewall and WAF, shell quarantined. Remediation: application component patched, uploads folder execution permissions removed, application and app pool credentials rotated, full scan clean. Verification: zero w3wp.exe child processes and zero new web files after cleanup; permanent detection rule requested (RB-SOC-027).',
    keywords: ['web shell', 'webshell', 'iis', 'w3wp', 'inetpub', 'aspx', 'dropper', 't1505.003', 't1190', 'servidor web', 'carga de archivos', 'file upload', 'backdoor', 'puerta trasera'],
