        expected: 'Listado de archivos con cuenta y proceso iniciador: explorer.exe señala copia manual; rar.exe o 7z.exe señala preparación previa de la fuga.',
        explanation: 'Clasifique el contenido por nombre y extensión (.pst, .xlsx, .kdbx, nominas*, contratos*) y sume el tamaño: el inventario exacto define el impacto y la ruta legal.',
