    english_customer_response_template: 'Hi {{USERNAME}}, our data loss prevention monitoring flagged a large copy of corporate files from your computer to a removable USB device. We disabled further writes to that device while we validate the activity. If this transfer was authorized, please reply with the approval record and the inventory of the device; if you did not perform it, stop using the computer and contact us immediately. Unauthorized transfers of corporate data have legal implications and are handled under our internal policy.',
