    escalation: 'Cualquier autenticación exitosa del atacante es P1: recoja evidencia del host (RB-SOC-028 adaptado a Linux), reconstruya la sesión con last y evalúe reconstrucción del host por posible implante, con el IR lead informado. Ataques sostenidos desde rangos completos escalan al equipo de redes para bloqueo de rango o geobloqueo.',
    english_customer_response_template: 'Hello, our monitoring detected a large number of failed password attempts against one of our internet-exposed Linux servers, a common automated attack. No successful access occurred: we blocked the attacking addresses at the host and at the perimeter firewall, and we are hardening the service to key-based authentication only. No action is required from any user; the system owner will be informed once the hardening completes.',
    english_technical_explanation: 'SSH brute force (T1110.001 password guessing) against exposed Linux host {{HOSTNAME}} at {{TIMESTAMP}}: thousands of failed authentications from {{SOURCE_IP}} visible in CommonSecurityLog (perimeter, port 22) and /var/log/auth.log. Success verification: zero "Accepted password" entries from attacking IPs; sessions reviewed with last and lastb. Containment: fail2ban ban (fail2ban-client set sshd banip) plus perimeter firewall block. Remediation: PasswordAuthentication disabled in sshd_config (key-based only), root login disabled, port restricted to corporate ranges, targeted account passwords rotated, UID 0 accounts audited. Verification: failed attempts ceased after blocking; monitoring continues for IP rotation.',
    keywords: ['ssh', 'fuerza bruta', 'brute force', 'fail2ban', 'auth.log', 't1110', 'password guessing', 'failed password', 'journalctl', 'sshd_config', 'linux', 'puerto 22', 'banip', 'lastb'],
