    english_customer_response_template: 'Hello, our web application firewall detected multiple SQL injection attempts against our public portal. All attempts were blocked at the perimeter and our review confirms no query reached the database. We blocked the attacking addresses, reinforced the firewall rule in blocking mode, and our development team will parameterize the affected queries as the permanent fix. The application remains available and no action is required from any user.',
    english_technical_explanation: 'SQL injection attempt wave (T1190) against the public portal at {{TIMESTAMP}}: payloads (union select, time-based sleep, tautologies) extracted from WAF logs in CommonSecurityLog RequestUrl; sources ranked by SourceIP. Backend exposure verified in access_combined (status and response_time): all requests returned WAF 403 with no anomalous latency; authorized time-based test by the application owner confirmed baseline latency only. Containment: attacking IPs blocked at WAF and host firewall, rule moved to blocking mode, rate limiting enabled. Root fix: parameterized queries and input validation requested from the development team; Sigma detection for the payload pattern requested (RB-SOC-027). Verification: zero post-block attempts reaching the backend.',
    keywords: ['sql injection', 'inyeccion sql', 'sqli', 'waf', 't1190', 'payload', 'union select', 'time-based', 'sleep', 'commonsecuritylog', 'requesturl', 'access_combined', 'consultas parametrizadas', 'parameterized queries'],
