    title: 'Credenciales expuestas en repositorio público: secret scanning y rotación inmediata',
    category: 'Compromiso de Cuentas',
    ticket_example: 'SOC{{TICKET_ID}} - Credentials exposed in public repository (secret scanning) - P1 - {{USERNAME}}',
